      const b = paidCategoriesByNameNoUserId[cp.client_name] || { subscription: 0, diet: 0, programs: 0, other: 0 };
      return { subscription: a.subscription + b.subscription, diet: a.diet + b.diet, programs: a.programs + b.programs, other: a.other + b.other };
