    // Id-first roster: every entry with a client_id that matches a real
    // profile is grouped under that profile's id, never its display name —
    // that's what keeps two clients named e.g. "Mike S." from ever having
    // their sessions, balance, or profile fields bleed into each other.
    // Only entries logged before client_id existed (no client_id at all)
    // fall back to name-matching, and even then only when the name is
    // unambiguous (exactly one current profile has it) — a name shared by
    // two+ profiles gets its untagged legacy entries shown as their own
    // separate "unmatched history" row instead of being guessed onto either
    // client.
    const roster = useMemo(() => {
      const profileById = {};
      profiles.forEach((p) => { profileById[p.id] = p; });
      const nameCounts = {};
      profiles.forEach((p) => { nameCounts[p.client_name] = (nameCounts[p.client_name] || 0) + 1; });
      const byId = {};
      const byName = {};
      allEntries.forEach((x) => {
        // A trainer's own self-log entries never match a *visible* profile
        // (its profile was deliberately filtered out of `profiles` above) —
        // without this check they'd fall into the byName "unmatched legacy
        // data" branch below and get synthesized into a fake "Unassigned"
        // client row (exactly the "Magali haj — trains with Unassigned" bug).
        if (x.clientId && selfLogClientIds.has(x.clientId)) return;
        if (x.clientId && profileById[x.clientId]) {
          (byId[x.clientId] = byId[x.clientId] || []).push(x);
        } else {
          (byName[x.clientName] = byName[x.clientName] || []).push(x);
        }
      });
      function rowFor(id, name, profile, list) {
        const sessions = new Set(list.map((x) => x.date)).size;
        const lastDate = list.reduce((max, x) => (x.date > max ? x.date : max), list[0]?.date || "");
        const vol7 = computeWeekVolume(list);
        return {
          id, name, sessions, lastDate, vol7, entries: list,
          profile: profile || null,
          trainerId: profile ? profile.trainer_id : null,
          clientEmail: profile ? profile.client_email : null,
          birthday: profile ? profile.birthday : null
        };
      }
      // Every registered client shows up here, even ones who haven't logged a
      // single workout yet — otherwise a brand-new client is invisible and can
      // never get assigned to a trainer in the first place.
      const rows = profiles.map((p) => {
        const legacyList = nameCounts[p.client_name] === 1 ? (byName[p.client_name] || []) : [];
        return rowFor(p.id, p.client_name, p, [...(byId[p.id] || []), ...legacyList]);
      });
      const coveredUnambiguousNames = new Set(profiles.filter((p) => nameCounts[p.client_name] === 1).map((p) => p.client_name));
      Object.entries(byName).forEach(([name, list]) => {
        if (coveredUnambiguousNames.has(name)) return;
        rows.push(rowFor(`name:${name}`, name, null, list));
      });
      return rows.sort((a, b) => (a.lastDate < b.lastDate ? 1 : -1));
    }, [allEntries, profiles, selfLogClientIds]);

    // Sept 18 2026 inspection fix: `roster` above already excludes a
    // trainer's own self-logged workouts (is_trainer_self_log rows) from
    // the client list itself, but `allEntries` — the raw, unfiltered fetch
    // — was still being passed straight into ManagerDashboard for the
    // platform-wide "sessions today/this month" totals. Any of the 17
