    // padding those numbers, the same "data you'd report to higher
    // management could be wrong" category as the very first dashboard fix
    // this project shipped. Same exclusion check as the roster builder
    // above, just applied to the entries list the Dashboard actually sees.
    const dashboardEntries = useMemo(
      () => allEntries.filter((x) => !(x.clientId && selfLogClientIds.has(x.clientId))),
      [allEntries, selfLogClientIds]
    );

    const ownerTrainer = useMemo(() => trainers.find((t) => t.email === OWNER_TRAINER_EMAIL), [trainers]);
    // Self-signed-up trainers waiting on approval (Sept 6 2026) — kept out of
    // browsableTrainers below so they don't show up in the normal roster (no
    // clients to show yet, and clicking in would land on a half-set-up
    // trainer page) until Jimmy approves them from the list rendered above it.
    const pendingTrainers = useMemo(() => trainers.filter((t) => t.is_approved === false), [trainers]);
    // Sept 15 2026, Jimmy: "how i delete this pending one" — the built-in
    // Self-Training bucket (SELF_TRAIN_EMAIL) isn't a real trainer, has
    // nothing to actually pay, and can't be deleted (it's what the 5
    // training-alone clients' trainer_id points at — deleting it would
    // orphan them). It used to sit inside browsableTrainers, which fed the
    // ⏳ Pending/✅ Paid split below — since it never has a trainer_payments
    // row, it always landed in "Pending" looking exactly like an unpaid
    // trainer, which is what Jimmy was trying to "delete." Excluded here so
    // it's never mistaken for one; it still gets its own always-visible
    // card lower down (selfTrainBucket) so the invite code stays reachable.
    const browsableTrainers = useMemo(() => trainers.filter((t) => t.email !== OWNER_TRAINER_EMAIL && t.email !== SELF_TRAIN_EMAIL && t.is_approved !== false), [trainers]);
    const selfTrainBucket = useMemo(() => trainers.find((t) => t.email === SELF_TRAIN_EMAIL) || null, [trainers]);
    // Sept 14 2026, Jimmy: search-filtered view of browsableTrainers for
    // the Trainers list's new search box — same name-or-email match as
    // ClientRosterList's search.
    const visibleBrowsableTrainers = useMemo(() => {
      const q = trainerSearch.trim().toLowerCase();
      if (!q) return browsableTrainers;
      return browsableTrainers.filter((t) => (t.name || "").toLowerCase().includes(q) || (t.email || "").toLowerCase().includes(q));
    }, [browsableTrainers, trainerSearch]);
    // Sept 14 2026, Jimmy: "2 sections for paid and pending trainers" — the
    // Trainers roster used to be one flat list with a per-card "no payment
    // yet" / "$X due" / "$X credit" badge you had to scan for. Splitting it
    // the same way the Clients tab was split: "pending" is never-paid OR
    // currently owing (the same two conditions the badges already flagged),
    // "paid" is everyone else (paid at least once and not currently owing).
    const trainerPaymentSplit = useMemo(() => {
      const paid = [], pending = [];
      visibleBrowsableTrainers.forEach((t) => {
        const bal = trainerBalanceFor(t.id);
        const neverPaid = !paidByTrainerId[t.id];
        const owes = bal != null && bal > 0;
        (neverPaid || owes ? pending : paid).push(t);
      });
      return { paid, pending };
    }, [visibleBrowsableTrainers, paidByTrainerId]);
    // Same as browsableTrainers but also drops the Self-Training bucket — used
    // anywhere trainers are treated as real people with real stats (the
    // dashboard's "by trainer" breakdown), so "Self-Training (no trainer)"
    // doesn't show up as if it were a trainer with clients and revenue.
    // browsableTrainers itself is left as-is for the Trainers roster tab,
    // which deliberately keeps Self-Training selectable with special-cased
    // display (see the "trainers" coachTab branch below).
    const realTrainersOnly = useMemo(() => trainers.filter((t) => t.email !== OWNER_TRAINER_EMAIL && t.email !== SELF_TRAIN_EMAIL), [trainers]);
    const myRoster = useMemo(() => roster.filter((r) => ownerTrainer && r.trainerId === ownerTrainer.id), [roster, ownerTrainer]);
    // Sept 14 2026, Jimmy: "can i have 2 section? clients who train alone
    // and clients with trainers?" — splits the main Clients roster by
    // whether a client's trainer_id points at the built-in Self-Training
    // bucket (see SELF_TRAIN_EMAIL/SELF_TRAIN_NAME up top) or at a real
    // trainer. Anyone with no trainer_id at all (never assigned) lands in
    // "With a trainer" too, same as trainerNameFor already calls that case
    // "Unassigned" rather than treating it as a deliberate self-train
    // choice — this is just the one existing roster split into two
    // groups, not a new data concept.
    const selfTrainBucketId = useMemo(() => {
      const t = trainers.find((tr) => tr.email === SELF_TRAIN_EMAIL);
      return t ? t.id : null;
    }, [trainers]);
    const selfTrainClients = useMemo(() => roster.filter((r) => selfTrainBucketId && r.trainerId === selfTrainBucketId), [roster, selfTrainBucketId]);
    const trainerAssignedClients = useMemo(() => roster.filter((r) => !(selfTrainBucketId && r.trainerId === selfTrainBucketId)), [roster, selfTrainBucketId]);

    // Sept 14 2026, Jimmy: "i want also here to see alone the clients who
    // paid per subscription and per diet and per program" — a second way
    // to group the same Clients roster, this time by what they've paid
    // for rather than who trains them. Reuses categoriesFor exactly as
    // ClientsBillingPanel already does (same subscription/diet/programs
    // split); a client can land in more than one group if they've paid
    // for more than one thing — these aren't mutually exclusive buckets
    // the way "trains alone vs with a trainer" is.
    const [clientsGroupBy, setClientsGroupBy] = useState("trainer");
    // Sept 14 2026, Jimmy: "add here also a section beside by trainer
    // training alone not down" — "With a trainer" and "Training alone"
    // used to stack vertically (scroll past a full trainer roster to reach
    // the self-training one below it). Same fix as the payment split: a
    // second-level pill switches between the two instead of stacking them.
    const [trainerSubView, setTrainerSubView] = useState("assigned");
    const subscriptionPaidClients = useMemo(() => roster.filter((r) => { const c = categoriesFor(r.profile); return c && c.subscription > 0; }), [roster]);
    const dietPaidClients = useMemo(() => roster.filter((r) => { const c = categoriesFor(r.profile); return c && c.diet > 0; }), [roster]);
    const programPaidClients = useMemo(() => roster.filter((r) => { const c = categoriesFor(r.profile); return c && c.programs > 0; }), [roster]);
    const trainerClientCounts = useMemo(() => {
      const counts = {};
      profiles.forEach((p) => { if (p.trainer_id) counts[p.trainer_id] = (counts[p.trainer_id] || 0) + 1; });
      return counts;
    }, [profiles]);
    // trainers, not browsableTrainers — the Self-Training bucket is
    // deliberately excluded from browsableTrainers now (see above) but its
    // own card still opens this same detail view by id.
    const selectedTrainer = trainers.find((t) => t.id === selectedTrainerId);
    const trainerRoster = useMemo(() => roster.filter((r) => r.trainerId === selectedTrainerId), [roster, selectedTrainerId]);

    function trainerNameFor(trainerId) {
      if (!trainerId) return "Unassigned";
      const t = trainers.find((tr) => tr.id === trainerId);
      return t ? t.name : "Unassigned";
    }

    // Takes the profile row directly (not a name) — there's no ambiguity to
    // resolve since the caller already has the right client's own profile.
    function balanceFor(cp) {
      if (!cp || cp.total_due == null) return null;
      // The name-matched legacy fallback is only safe to trust when that
      // name is unique across current clients — otherwise an old untagged
      // payment belonging to ONE of two same-named clients would get
      // credited to BOTH of their balances (Sept 6 2026 deep bug search: a
      // real double-count, not just a theoretical one, since client names
      // in this app aren't guaranteed unique).
      const sameNameCount = profiles.filter((p) => p.client_name === cp.client_name).length;
      const legacyByName = sameNameCount === 1 ? (paidByNameNoUserId[cp.client_name] || 0) : 0;
      const paid = (cp.user_id ? (paidByUserId[cp.user_id] || 0) : 0) + legacyByName;
      return Number(cp.total_due) - paid;
    }

    function resolveClientById(id) {
      if (typeof id === "string" && id.indexOf("name:") === 0) return null; // legacy row with no matching profile
      return profiles.find((p) => p.id === id) || null;
    }

    function trainerBalanceFor(trainerId) {
      const t = trainers.find((tr) => tr.id === trainerId);
      if (!t || t.amount_due == null) return null;
      return Number(t.amount_due) - (paidByTrainerId[trainerId] || 0);
    }

    // Sept 11 2026, Jimmy: brand pass — was window.confirm(); now opens the
    // on-brand ConfirmDialog (see confirmDialog state + its render near the
    // bottom of this component) and only runs the actual delete once the
    // dialog's own Delete button is tapped. Logic itself is unchanged.
    function handleDeleteClient(id) {
      // id is a roster row id — a real profile id, or a "name:X" pseudo-id
      // for a legacy row with no matching profile (see the roster builder).
      // Resolving by id first, before doing anything else, is what makes
      // this safe when two clients share a display name: cp is always THIS
      // specific client's own profile row, never a name-ambiguous guess.
      const cp = resolveClientById(id);
      const name = cp ? cp.client_name : String(id).replace(/^name:/, "");
      // Sept 17 2026, Jimmy: "if me as owner i delete someone automatically
      // will be deleted?" — previously this only wiped the app-side rows and
      // deliberately left the login alone (see the old copy of this message,
      // still true for a legacy client with no login at all). Now, when the
      // client has a real login, this also calls owner_delete_client_account
      // (see supabase_owner_delete_accounts.sql) which deletes their
      // auth.users row too — same end result as if the client had used
      // "Delete my account" themselves. hasLogin decides which message —
      // and which cleanup path — applies.
      const hasLogin = !!(cp && cp.user_id);
      setConfirmDialog({
        title: "Delete this client?",
        message: hasLogin
          ? `Delete ${name} entirely? This removes their profile, workout history, payment records, and their login — they won't be able to sign back in. This can't be undone.`
          : `Delete ${name} entirely? This removes their profile, workout history, and payment records, and can't be undone. (They don't have a login account yet, so there's nothing else to remove.)`,
        confirmLabel: "Delete client",
        onConfirm: async () => {
          setConfirmDialog(null);
          setAllEntries((prev) => prev.filter((x) => (cp && cp.id ? x.clientId !== cp.id : x.clientName !== name)));
          setProfiles((prev) => prev.filter((p) => (cp && cp.id ? p.id !== cp.id : p.client_name !== name)));
          setAllPayments((prev) => prev.filter((p) => (cp && cp.user_id ? p.user_id !== cp.user_id : p.client_name !== name)));
          if (selectedClient === id) setSelectedClient(null);
          if (sb) {
            if (hasLogin) {
              const { error: rpcErr } = await sb.rpc("owner_delete_client_account", { target_user_id: cp.user_id });
              if (rpcErr) {
                // RPC not deployed yet (or failed) — fall back to the old
                // app-data-only cleanup so the client still disappears from
                // the roster now; their login is left for the SQL script to
                // be run, same as before this feature existed.
                await sb.from("workout_entries").delete().eq("client_id", cp.id);
                await sb.from("client_program_assignments").delete().eq("client_id", cp.id);
                await sb.from("client_payments").delete().eq("user_id", cp.user_id);
                await sb.from("client_profiles").delete().eq("id", cp.id);
              }
            } else if (cp && cp.id) {
              await sb.from("workout_entries").delete().eq("client_id", cp.id);
              await sb.from("client_program_assignments").delete().eq("client_id", cp.id);
              await sb.from("client_profiles").delete().eq("id", cp.id);
            } else {
              await sb.from("workout_entries").delete().eq("client_name", name);
              await sb.from("client_profiles").delete().eq("client_name", name);
            }
          }
        }
      });
    }

    // Sept 14 2026, Jimmy: "add ... a delete option button" on the Diet plan
    // requests / Program requests "Paid" lists — same on-brand ConfirmDialog
    // as every other delete in this view, just removing one client_payments
    // row (e.g. logged by mistake, wrong client, test entry) instead of a
    // whole client. Doesn't touch the client's plan/program unlock itself —
    // just the payment record — same as any other billing correction.
    function handleDeletePayment(payment) {
      setConfirmDialog({
        title: "Delete this payment?",
        message: `Delete the $${Number(payment.amount || 0).toLocaleString()} payment from ${payment.client_name || "this client"} (${payment.paid_on ? fmtDate(payment.paid_on.slice(0, 10)) : "no date"})? This can't be undone and won't undo their plan/program unlock automatically.`,
        confirmLabel: "Delete payment",
        onConfirm: async () => {
          setConfirmDialog(null);
          setAllPayments((prev) => prev.filter((p) => p.id !== payment.id));
          if (sb) await sb.from("client_payments").delete().eq("id", payment.id);
        }
      });
    }

    function handleClearWorkouts(id) {
      const cp = resolveClientById(id);
      const name = cp ? cp.client_name : String(id).replace(/^name:/, "");
      setConfirmDialog({
        title: "Clear workout history?",
        message: `Clear all logged workouts for ${name}? Their profile and payment history stay intact — only session history is removed. Can't be undone.`,
        confirmLabel: "Clear history",
        onConfirm: async () => {
          setConfirmDialog(null);
          setAllEntries((prev) => prev.filter((x) => (cp && cp.id ? x.clientId !== cp.id : x.clientName !== name)));
          if (sb) {
            if (cp && cp.id) await sb.from("workout_entries").delete().eq("client_id", cp.id);
            else await sb.from("workout_entries").delete().eq("client_name", name);
          }
        }
      });
    }

    async function handleAddTrainer() {
      setAddTrainerError("");
      const name = newTrainerName.trim();
      const emailAddr = newTrainerEmail.trim().toLowerCase();
      if (!name) { setAddTrainerError("Enter a name."); return; }
      if (!emailAddr || !emailAddr.includes("@")) { setAddTrainerError("Enter a valid email."); return; }
      if (!sb) { setAddTrainerError("Backend not configured yet."); return; }
      setAddingTrainer(true);
      const { data: existing } = await sb.from("trainers").select("id").eq("email", emailAddr).maybeSingle();
      if (existing) {
        setAddingTrainer(false);
        setAddTrainerError("A trainer with that email already exists.");
        return;
      }
      const { data, error: err } = await sb.from("trainers").insert([{ name, email: emailAddr, phone: newTrainerPhone.trim() || null, invite_code: randomInviteCode() }]).select();
      setAddingTrainer(false);
      if (err || !data) { setAddTrainerError("Couldn't add that trainer. Try again."); return; }
      setTrainers((prev) => [...prev, data[0]].sort((a, b) => (a.name || "").localeCompare(b.name || "")));
      setNewTrainerName(""); setNewTrainerEmail(""); setNewTrainerPhone(""); setShowAddTrainer(false);
    }

    async function handleUpdateTrainerField(trainerId, field, value) {
      // Sept 19 2026 inspection fix: email is this trainer's login identity
      // (matched by exact string at login, see the trainer-check effect) —
      // give it the same format/lowercase/duplicate checks handleAddTrainer
      // already does for a brand-new trainer, instead of writing whatever
      // was typed straight through. A rejected edit leaves the field
      // showing the last-good value (EditableStat resyncs its draft from
      // the unchanged `value` prop) and surfaces why via trainerFieldError.
      if (field === "email") {
        setTrainerFieldError("");
        const normalized = (value || "").trim().toLowerCase();
        if (!normalized || !normalized.includes("@")) {
          setTrainerFieldError("Enter a valid email.");
          return;
        }
        if (sb) {
          const { data: existing } = await sb.from("trainers").select("id").eq("email", normalized).neq("id", trainerId).maybeSingle();
          if (existing) {
            setTrainerFieldError("A trainer with that email already exists.");
            return;
          }
        }
        setTrainers((prev) => prev.map((t) => (t.id === trainerId ? { ...t, email: normalized } : t)));
        if (sb) await sb.from("trainers").update({ email: normalized }).eq("id", trainerId);
        return;
      }
      setTrainers((prev) => prev.map((t) => (t.id === trainerId ? { ...t, [field]: value } : t)));
      if (sb) await sb.from("trainers").update({ [field]: value }).eq("id", trainerId);
    }

    // Sept 13 2026, Jimmy: "every delete button in the app... show inside
    // the page not above" — was window.confirm(); confirmDeleteTrainer just
    // tracks whether the inline "are you sure" block below the Delete
    // trainer button is open, same idea as every other delete in the app
    // now. Only one trainer's detail page is ever open at once here, so a
    // plain boolean (not per-id) is enough.
    const [confirmDeleteTrainer, setConfirmDeleteTrainer] = useState(false);
    // Sept 18 2026, review item #15: this was the one remaining delete flow
    // still popping a plain browser alert() box instead of the app's own
    // styled errorBanner (every other error in the app went through this
    // same setError/errorBanner pattern back on Sept 13).
    const [deleteTrainerError, setDeleteTrainerError] = useState("");
    // Sept 19 2026 inspection fix: every other delete flow in the app
    // disables its confirm button while the request is in flight — this one
    // didn't, so a fast double-click could fire owner_delete_trainer_account
    // twice concurrently (the second call just fails against an
    // already-deleted row, but it's an inconsistency worth closing).
    const [deletingTrainer, setDeletingTrainer] = useState(false);
    // Sept 19 2026 inspection fix: editing a trainer's email (below, via
    // handleUpdateTrainerField's special-cased "email" branch) had none of
    // handleAddTrainer's format/lowercase/duplicate checks — a typo or a
    // case mismatch (Bob@ vs bob@) would silently break that trainer's next
    // login (matched by exact email string), with nothing in the UI
    // warning it happened. This surfaces that validation's result.
    const [trainerFieldError, setTrainerFieldError] = useState("");
    useEffect(() => { setTrainerFieldError(""); }, [selectedTrainerId]);
    function deleteTrainerMessage(trainerId) {
      const t = trainers.find((x) => x.id === trainerId);
      if (!t) return "";
      const clientCount = trainerClientCounts[trainerId] || 0;
      // Sept 17 2026, Jimmy: same owner-side "actually delete the login too"
      // change as handleDeleteClient — see owner_delete_trainer_account in
      // supabase_owner_delete_accounts.sql. Previously this note said the
      // login would still work; now it doesn't, so the copy has to say so.
      const loginNote = " Their login will be deleted too — they won't be able to sign back in.";
      // Sept 19 2026 inspection fix: any session already on the Rota for
      // this trainer was left pointing at a trainer who no longer exists,
      // with no heads-up here that you'd need to find and deal with those
      // separately (they still show, just as "Unassigned"). Said plainly
      // now, same way the client-reassignment note already is.
      const sessionsNote = " Any sessions already booked with them will show as \"Unassigned\" on the Rota — reassign or remove those separately.";
      return (clientCount > 0
        ? `Delete ${t.name}? Their ${clientCount} client${clientCount === 1 ? "" : "s"} will become unassigned — you can reassign them anytime.`
        : `Delete ${t.name}? This can't be undone.`) + sessionsNote + loginNote;
    }
    async function handleDeleteTrainer(trainerId) {
      if (deletingTrainer) return;
      const t = trainers.find((x) => x.id === trainerId);
      if (!t) return;
      if (t.email === SELF_TRAIN_EMAIL) { setDeleteTrainerError("\"Self-Training\" is a built-in bucket for clients without a trainer — it can't be deleted."); return; }
      setDeleteTrainerError("");
      // Sept 19 2026 inspection fix: this used to close the confirm bar
      // (setConfirmDeleteTrainer(false)) in the same tick as setting
      // deletingTrainer(true) — React batches both into one render, so the
      // very next paint showed confirmDeleteTrainer=false, which picks the
      // plain, fully-enabled "Delete trainer" button instead of the
      // "Deleting…" busy one. It looked like the tap did nothing while the
      // delete was still running, and — since deleteTrainerError only
      // renders inside the confirmDeleteTrainer branch — a real failure's
      // error message was never visible either. Now stays open (with its
      // busy/disabled state and any error) until the operation actually
      // finishes; only Cancel and a real success close it.
      setDeletingTrainer(true);
      if (sb) {
        const { error: rpcErr } = await sb.rpc("owner_delete_trainer_account", { target_trainer_id: trainerId });
        if (rpcErr) {
          // Sept 18 2026: owner_delete_trainer_account deliberately REFUSES
          // (raise exception) for a protected row — a real multi-tenant gym
          // owner (is_owner = true) or the legacy __owner__ placeholder —
          // see supabase_owner_delete_accounts.sql. That refusal used to
          // land in this same rpcErr branch as "the RPC just isn't deployed
          // yet," so the raw fallback below ran either way and actually
          // deleted the exact row the SQL was trying to protect — a real
          // gym owner's trainer row, breaking their GymOwnerView and
          // orphaning their login. Only fall back to the old roster-only
          // cleanup when the function is genuinely missing; any other
          // error (including that explicit refusal) stops here and tells
          // you, instead of silently doing the delete anyway.
          const fnMissing = rpcErr.code === "42883" || rpcErr.code === "PGRST202" || /function .* does not exist|could not find the function/i.test(rpcErr.message || "");
          if (!fnMissing) {
            setDeleteTrainerError(rpcErr.message || "Couldn't delete that trainer — try again.");
            setDeletingTrainer(false);
            return;
          }
          await sb.from("client_profiles").update({ trainer_id: null }).eq("trainer_id", trainerId);
          await sb.from("trainers").delete().eq("id", trainerId);
        }
        // Sept 19 2026 inspection fix: neither the RPC nor this fallback
        // touched scheduled_sessions — any booking already on the Rota for
        // this trainer was left with a trainer_id pointing at a row that no
        // longer exists. It degrades gracefully (shows as "Unassigned"
        // rather than crashing), but leaving a real dangling reference
        // around when it's this easy to clear is worse than just clearing
        // it — same "becomes unassigned" outcome the client reassignment
        // above already gives, just for sessions instead of clients.
        await sb.from("scheduled_sessions").update({ trainer_id: null }).eq("trainer_id", trainerId);
      }
      setTrainers((prev) => prev.filter((x) => x.id !== trainerId));
      setProfiles((prev) => prev.map((p) => (p.trainer_id === trainerId ? { ...p, trainer_id: null } : p)));
      setAllTrainerPayments((prev) => prev.filter((p) => p.trainer_id !== trainerId));
      setConfirmDeleteTrainer(false);
      setSelectedTrainerId(null);
      setDeletingTrainer(false);
    }

    // Rejecting a pending self-signup is just a delete with clearer wording —
    // there's never a client to worry about reassigning at this stage, so the
    // shared confirm dialog's messaging doesn't fit; skip straight to a
    // reject-specific confirm instead of reusing handleDeleteTrainer's.
    // Sept 7 2026, Jimmy: "when he logs in and creates an account for the
    // first time [he should] directly see the payment whish and i accept
    // him once after paying" — approving and confirming the first payment
    // used to be two separate manual actions on two separate screens
    // (a plain "Approve" here, then later "Mark this month's payment
    // received" on Trainers → Billing), which also meant a trainer had to
    // log back in an extra time in between. Now a pending trainer sees the
    // Whish payment screen immediately on their first login (see the
    // render-order change near TrainerFirstPaymentDueScreen below), and
    // this single action both approves them AND logs their first payment
    // together — same amount/next-due-date mini-form pattern as
    // TrainersBillingPanel's "Mark this month's payment received" flow, so
    // it should feel familiar rather than like a second, different UI.
    const [approvingId, setApprovingId] = useState(null);
    const [approveAmount, setApproveAmount] = useState("");
    const [approveDate, setApproveDate] = useState("");
    const [approveSaving, setApproveSaving] = useState(false);
    const [approveError, setApproveError] = useState("");

    function openApprove(t) {
      setApproveError("");
      setApprovingId(t.id);
      setApproveAmount(String(Number(t.rate_monthly) || B2B_FLAT_RATE_MONTHLY));
      const d = new Date();
      d.setDate(d.getDate() + 30);
      setApproveDate(d.toISOString().slice(0, 10));
    }

    async function handleApproveAndConfirmPayment(trainerId) {
      const t = trainers.find((x) => x.id === trainerId);
      if (!t) return;
      setApproveError("");
      const amt = Number(approveAmount);
      if (!approveAmount || Number.isNaN(amt) || amt <= 0) { setApproveError("Enter a valid amount."); return; }
      if (!approveDate) { setApproveError("Pick a next payment date."); return; }
      if (!sb) { setApproveError("Backend not configured yet."); return; }
      setApproveSaving(true);
      const updates = { is_approved: true, next_payment_date: approveDate, rate_monthly: amt };
      const { error: updErr } = await sb.from("trainers").update(updates).eq("id", trainerId);
      if (updErr) {
        setApproveSaving(false);
        setApproveError("Couldn't save that. Try again.");
        return;
      }
      const { error: payErr } = await sb.from("trainer_payments").insert([{
        trainer_id: t.id, trainer_name: t.name, amount: amt, paid_on: todayISO(),
        note: `First payment — paid through ${approveDate}`
      }]);
      setTrainers((prev) => prev.map((x) => (x.id === trainerId ? { ...x, ...updates } : x)));
      if (payErr) {
        setApproveSaving(false);
        setApproveError("Approved, but couldn't log the payment — add it manually on Trainers → Billing so the app unlocks for them.");
        return;
      }
      setApproveSaving(false);
      setApprovingId(null);
    }

    // Sept 13 2026, Jimmy: inline "are you sure" instead of window.confirm()
    // — tracks which pending trainer's Reject is mid-confirm, so only that
    // one card shows the inline bar.
    const [confirmRejectId, setConfirmRejectId] = useState(null);
    async function handleRejectTrainer(trainerId) {
      const t = trainers.find((x) => x.id === trainerId);
      if (!t) return;
      setConfirmRejectId(null);
      if (sb) await sb.from("trainers").delete().eq("id", trainerId);
      setTrainers((prev) => prev.filter((x) => x.id !== trainerId));
    }

    // All four now take the roster row's id, resolved to a profile via
    // resolveClientById — never a bare name, since two clients can share a
    // display name and a name lookup could silently resolve to the wrong one.
    async function handleAssignTrainer(id, trainerId) {
      const cp = resolveClientById(id);
      if (!cp) return;
      const prevTrainerId = cp.trainer_id;
      setProfiles((prev) => prev.map((p) => (p.id === cp.id ? { ...p, trainer_id: trainerId || null } : p)));
      if (sb) await sb.from("client_profiles").update({ trainer_id: trainerId || null }).eq("id", cp.id);
      // Sept 17 2026, Jimmy: "the trainers how they get notifications" — new
      // client assigned is one of the three events he wants pushed. Only
      // fires on an actual change to a real trainer (not a no-op re-save,
      // not unassigning) — notifyTrainer itself is a safe no-op for the
      // Self-Training bucket row since it never has a real login.
      if (trainerId && trainerId !== prevTrainerId) notifyTrainer(trainerId, `${cp.client_name} was assigned to you.`);
    }

    async function handleUpdateGoal(id, daysPerWeek) {
      const cp = resolveClientById(id);
      if (!cp) return;
      setProfiles((prev) => prev.map((p) => (p.id === cp.id ? { ...p, days_per_week: daysPerWeek } : p)));
      if (sb) await sb.from("client_profiles").update({ days_per_week: daysPerWeek }).eq("id", cp.id);
      // This "Trains/week" dropdown is a separate control from the generic
      // EditableStat fields above (predates them) — it was missed when the
      // BMR/target recalc-on-edit fix went in, so activity level never
      // refreshed when someone changed training days here (Sept 6 2026 deep
      // bug search).
      recalcBmrAndTargets(cp.user_id, cp.client_name, {
        weight: cp.weight_kg, height: cp.height_cm, age: cp.age,
        gender: cp.gender, daysPerWeek, goal: cp.goal
      });
    }

    async function handleUpdateTotalDue(id, totalDue) {
      const cp = resolveClientById(id);
      if (!cp) return;
      setProfiles((prev) => prev.map((p) => (p.id === cp.id ? { ...p, total_due: totalDue } : p)));
      if (sb) await sb.from("client_profiles").update({ total_due: totalDue }).eq("id", cp.id);
    }

    // Sept 18 2026 inspection fix: the onUnlockDietPlan callback below used
    // to compute "current total_due (from local state) + amount" and hand
    // that absolute number to handleUpdateTotalDue above — two near-
    // simultaneous unlocks for the same client (different devices/sessions)
    // could race, and whichever write landed last would silently clobber
    // the other's addition since neither read the OTHER write first. This
    // does the read+add atomically in one DB statement via an RPC instead,
    // with a same-shape fallback (a fresh read right before writing, not
    // whatever's already sitting in local state) if that RPC isn't deployed
    // yet — see supabase_increment_total_due.sql.
    async function handleIncrementTotalDue(id, amount) {
      const cp = resolveClientById(id);
      if (!cp) return;
      if (!sb) { setProfiles((prev) => prev.map((p) => (p.id === cp.id ? { ...p, total_due: (Number(p.total_due) || 0) + amount } : p))); return; }
      const { data, error: rpcErr } = await sb.rpc("increment_client_total_due", { target_client_id: cp.id, amount });
      if (!rpcErr && data != null) {
        setProfiles((prev) => prev.map((p) => (p.id === cp.id ? { ...p, total_due: Number(data) } : p)));
        return;
      }
      const { data: freshRow } = await sb.from("client_profiles").select("total_due").eq("id", cp.id).maybeSingle();
      const newTotal = (Number(freshRow && freshRow.total_due) || 0) + amount;
      await sb.from("client_profiles").update({ total_due: newTotal }).eq("id", cp.id);
      setProfiles((prev) => prev.map((p) => (p.id === cp.id ? { ...p, total_due: newTotal } : p)));
    }

    async function handleUpdateProfileField(id, field, value) {
      const cp = resolveClientById(id);
      if (!cp) return;
      const prevValue = cp[field];
      setProfiles((prev) => prev.map((p) => (p.id === cp.id ? { ...p, [field]: value } : p)));
      if (sb) {
        const { error: err } = await sb.from("client_profiles").update({ [field]: value }).eq("id", cp.id);
        // Sept 8 2026: revert on a failed save instead of leaving the
        // unsaved value showing — same fix as the trainer/client weight and
        // My Profile edit paths, applied here for consistency.
        if (err) {
          setProfiles((prev) => prev.map((p) => (p.id === cp.id ? { ...p, [field]: prevValue } : p)));
          return;
        }
      }
      // Keep BMR/macro targets fresh when a manager edits a client's body
      // stats on her behalf too, not just when she edits them herself.
      if (["weight_kg", "height_cm", "age", "gender", "days_per_week", "goal"].includes(field)) {
        const updated = { ...cp, [field]: value };
        recalcBmrAndTargets(updated.user_id, updated.client_name, {
          weight: updated.weight_kg, height: updated.height_cm, age: updated.age,
          gender: updated.gender, daysPerWeek: updated.days_per_week, goal: updated.goal
        });
      }
    }

